#include <iostream>
#include <vector>
#include <cstdio>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int w, b;
    cin >> w >> b;

    vector<double> prev(b + 1, 0.0), cur(b + 1, 0.0);

    for (int i = 1; i <= w; ++i) {
        fill(cur.begin(), cur.end(), 0.0);
        cur[0] = 1.0;

        for (int j = 1; j <= b; ++j) {
            cur[j] = static_cast<double>(i) / (i + j);

            if (j >= 3) {
                cur[j] += static_cast<double>(j) / (i + j)
                        * static_cast<double>(j - 1) / (i + j - 1)
                        * static_cast<double>(j - 2) / (i + j - 2)
                        * cur[j - 3];
            }

            if (j >= 2) {
                cur[j] += static_cast<double>(j) / (i + j)
                        * static_cast<double>(j - 1) / (i + j - 1)
                        * static_cast<double>(i) / (i + j - 2)
                        * prev[j - 2];
            }
        }

        prev.swap(cur);
    }

    printf("%.9f", prev[b]);
    return 0;
}

